return {
  absorb: {
    hook: "onEvent",
    eventType: "incomingEntityWoundDamage",
    async promptOnPlayer(H, actor) {
      if (!H.condition.has(actor, "ready")) return false;
      if (!await H.ask.confirm({
        title: "Metal Armour",
        bodyHtml: "<p>Expend Ready to reduce Wound damage by 1?</p>",
        yesLabel: "Expend Ready",
        noLabel: "Keep Ready",
      })) return false;
      await H.condition.set(actor, "ready", false);
      await H.chat.post("Metal: expend Ready to reduce Wound damage by 1.", actor);
      return { damageReduction: 1 };
    },
  },
};
